function showPage(next){page=next;const names={home:'Inicio',channels:'Todos los canales',multiview:'Multiview',recordings:'Recordings',favorites:'Favoritos',editor:'Editor de listas',playlist:'Reproducir lista',settings:'Personalización',help:'Ayuda y compatibilidad'};Object.keys(names).forEach(k=>{const el=$('#page'+k[0].toUpperCase()+k.slice(1));if(el)el.classList.toggle('hidden',k!==next)});$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===next));$('#pageTitle').textContent=names[next]||'Inicio';$('#sidebar').classList.remove('open');if(next==='home')renderHome();if(next==='multiview')renderMultiview();if(next==='channels'){playbackPlaylistId=null;updateGroups();renderChannelsPage()}if(next==='playlist')renderPlaylistPlayback();if(next==='favorites')renderFavorites();if(next==='editor')renderEditorList();if(next==='settings')renderSettings()}
function openModal(title,eyebrow,body){$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow||'TU BIBLIOTECA';$('#modalBody').innerHTML=body;$('#modalBackdrop').classList.remove('hidden');setTimeout(()=>$('#modalBody input:not([type=file]),#modalBody textarea')?.focus(),60)}function closeModal(){$('#modalBackdrop').classList.add('hidden');$('#modalBody').innerHTML=''}
function addModal(){openModal('Añadir una lista','AMPLÍA TU BIBLIOTECA',`<div class="choice-row"><button class="choice-card" data-modal-action="file"><strong>⇧ Importar archivo</strong><small>Selecciona un archivo .m3u o .m3u8 desde tu dispositivo.</small></button><button class="choice-card" data-modal-action="url"><strong>↗ Importar desde URL</strong><small>Usa un enlace a una lista remota compatible con el navegador.</small></button><button class="choice-card" data-modal-action="paste"><strong>▤ Pegar contenido</strong><small>Pega el texto M3U de una lista que ya tengas.</small></button><button class="choice-card" data-modal-action="create"><strong>＋ Crear una lista</strong><small>Construye una lista con los canales que quieras.</small></button><button class="choice-card" data-modal-action="single"><strong>▶ Añadir un solo canal</strong><small>Crea una lista mínima con una única señal.</small></button></div><p class="field-hint" style="margin-top:15px">Las listas remotas pueden fallar si el servidor no permite solicitudes desde otras páginas (CORS). Tus datos se guardan localmente en este navegador.</p>`)}
function importUrlModal(){openModal('Importar desde URL','LISTA REMOTA',`<form id="urlImportForm" class="modal-form"><div class="field"><label for="playlistUrl">URL de la lista</label><input id="playlistUrl" type="url" placeholder="https://ejemplo.com/lista.m3u" required><span class="field-hint">La dirección se solicita directamente desde tu navegador. No pegues enlaces con contraseñas si no confías en el sitio.</span></div><div class="field"><label for="urlListName">Nombre de la lista (opcional)</label><input id="urlListName" placeholder="Mi lista"></div><div class="modal-footer"><button type="button" class="secondary-btn" data-modal-action="back">Volver</button><button class="primary-btn" type="submit">Importar lista</button></div></form>`)}
