function createPlaylist(name='Mi lista nueva'){const p={id:id(),name,channels:[],createdAt:new Date().toISOString()};db.playlists.push(p);selectedPlaylist=p.id;activeEditor=p.id;save();refresh();showPage('editor');renderEditorList();renderEditorWorkspace(p.id);return p}
function importText(text,name){const parsed=TesitoPlaylist.parse(text,name||'Lista importada');if(!parsed.channels.length){toast('No encontramos canales con dirección en este contenido M3U.','error');return false}const p={id:id(),name:name||parsed.name,channels:parsed.channels,createdAt:new Date().toISOString()};db.playlists.push(p);selectedPlaylist=p.id;activeEditor=p.id;save();closeModal();refresh();showPage('editor');renderEditorList();renderEditorWorkspace(p.id);toast(`Lista importada: ${p.channels.length} canales.`,'success');return true}

function renderSettings(){const size=$('#cardSizeSetting');if(size)size.value=db.settings.cardSize||'comfortable';const keys=$('#keyboardSetting');if(keys)keys.checked=db.settings.keyboardShortcuts!==false;const qa=$('#quickAccessSetting');if(qa)qa.value=db.settings.quickAccess||'history';const resume=$('#resumeSetting');if(resume)resume.checked=db.settings.resumeLast!==false}
