function cloneJSON(x){return JSON.parse(JSON.stringify(x))}
function pushEditorUndo(p){if(!p)return;editorUndo.push({pid:p.id,channels:cloneJSON(p.channels||[]),name:p.name});if(editorUndo.length>30)editorUndo.shift();editorRedo=[]}
function restoreEditorSnapshot(stack,target){const snap=stack.pop();if(!snap){toast('No hay más cambios para recuperar.');return}const p=db.playlists.find(x=>x.id===snap.pid);if(!p)return;target.push({pid:p.id,channels:cloneJSON(p.channels||[]),name:p.name});p.channels=cloneJSON(snap.channels);p.name=snap.name;save();refresh();renderEditorWorkspace(p.id);toast('Versión restaurada.','success')}
function editorUndoAction(){restoreEditorSnapshot(editorUndo,editorRedo)}function editorRedoAction(){restoreEditorSnapshot(editorRedo,editorUndo)}
