function normalizeChannelName(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').replace(/\b(?:hd|fhd|uhd|4k|sd)\b/g,' ').replace(/[^a-z0-9]+/g,'').trim()}
function scanEditorDuplicates(){
 const rows=$$('#editorRows tr'); const byUrl=new Map(),byName=new Map();
 rows.forEach((row)=>{const name=row.querySelector('[data-field="name"]')?.value.trim()||'Canal sin nombre';const rowId=row.dataset.rowId;const urls=[row.querySelector('[data-field="url"]')?.value.trim()||''];const alt=row.querySelector('[data-field="signals"]')?.value||'';alt.split(/\r?\n/).forEach(line=>{const parts=line.split('|');if(parts.length>1)urls.push(parts.slice(1).join('|').trim())});
  [...new Set(urls.filter(Boolean).map(normalizeMatch))].forEach(url=>{if(!byUrl.has(url))byUrl.set(url,[]);byUrl.get(url).push({row,rowId,name,url})});
  const nameKey=normalizeChannelName(name);if(nameKey.length>=3){if(!byName.has(nameKey))byName.set(nameKey,[]);byName.get(nameKey).push({row,rowId,name,url:urls.find(Boolean)||''})}
 });
 const groups=[...Array.from(byUrl.entries()).map(([url,items])=>({type:'url',key:url,items:[...new Map(items.map(x=>[x.rowId,x])).values()]})).filter(g=>g.items.length>1),...Array.from(byName.entries()).map(([key,items])=>({type:'name',key,items:[...new Map(items.map(x=>[x.rowId,x])).values()]})).filter(g=>g.items.length>1)];
 if(!groups.length){openModal('Revisión de duplicados','EDITOR DE LISTAS',`<div class="modal-form"><p class="success-note">No se encontraron nombres ni URLs duplicados entre canales de esta lista.</p><p class="field-hint">Se revisó la lista abierta, incluidas las señales alternativas. Los nombres se comparan ignorando mayúsculas, tildes, espacios, signos y etiquetas comunes como HD/4K. Las coincidencias son sugerencias: verifica antes de unir.</p><div class="modal-footer"><button class="primary-btn" data-modal-action="close">Cerrar</button></div></div>`);return}
 window.__tesitoEditorDupGroups=groups;
 const urlCount=groups.filter(g=>g.type==='url').length,nameCount=groups.filter(g=>g.type==='name').length;
 const body=`<p>Encontré <b>${urlCount} grupos por URL</b> y <b>${nameCount} grupos por nombre</b> en esta lista.</p><p class="field-hint">Marca cualquier grupo que quieras unir. Si dos canales tienen el mismo nombre aunque sus URLs sean distintas, puedes convertirlos en un solo canal con varias señales. Se conservará el primer canal seleccionado como base y se agregarán las señales únicas. Revisa cada grupo antes de aplicar.</p>${groups.map((g,i)=>`<div class="maintenance-group"><label style="display:flex;gap:9px;align-items:flex-start"><input type="checkbox" data-editor-dup-group="${i}"><span><b>${g.type==='name'?'Nombre repetido':'URL repetida'} · ${g.items.length} canales</b><br>${g.items.map(x=>safe(x.name)).join(' · ')}${g.type==='url'?`<br><code>${safe(g.items[0].url)}</code>`:''}</span></label></div>`).join('')}<div class="modal-footer"><button class="small-btn" data-modal-action="close">Cancelar</button><button class="primary-btn" id="mergeEditorDuplicates">Unir en un canal con varias señales</button></div>`;
 openModal('Duplicados de esta lista','EDITOR DE LISTAS',`<div class="modal-form">${body}</div>`)
}
function mergeEditorDuplicates(){
 const currentPlaylist=db.playlists.find(p=>p.id===activeEditor);pushEditorUndo(currentPlaylist);
 const groups=window.__tesitoEditorDupGroups||[];const selected=$$('[data-editor-dup-group]:checked').map(x=>groups[Number(x.dataset.editorDupGroup)]).filter(Boolean);
 if(!selected.length){toast('Marca al menos un grupo para unir.','error');return}
 const rows=$$('#editorRows tr');const data=new Map(rows.map(row=>[row.dataset.rowId,{row,id:row.dataset.rowId,name:row.querySelector('[data-field="name"]').value.trim()||'Canal sin nombre',url:row.querySelector('[data-field="url"]').value.trim(),group:row.querySelector('[data-field="group"]').value.trim(),logo:row.querySelector('[data-field="logo"]').value.trim(),signals:row.querySelector('[data-field="signals"]').value} ]));
 // Build connected components so overlapping selected groups are merged only once.
 const parent=new Map([...data.keys()].map(k=>[k,k]));const find=x=>{let r=x;while(parent.get(r)!==r)r=parent.get(r);while(parent.get(x)!==x){const n=parent.get(x);parent.set(x,r);x=n}return r};const union=(a,b)=>{if(!data.has(a)||!data.has(b))return;const ra=find(a),rb=find(b);if(ra!==rb)parent.set(rb,ra)};
 selected.forEach(g=>{const ids=[...new Set(g.items.map(x=>x.rowId))].filter(id=>data.has(id));for(let i=1;i<ids.length;i++)union(ids[0],ids[i])});
 const components=new Map();data.forEach((v,k)=>{const root=find(k);if(!components.has(root))components.set(root,[]);components.get(root).push(k)});const removed=new Set();
 components.forEach(ids=>{if(ids.length<2)return;const base=data.get(ids[0]);const sigs=[];const add=(name,url)=>{url=String(url||'').trim();if(url)sigs.push({name:name||'Señal alternativa',url})};add('Señal principal',base.url);base.signals.split(/\r?\n/).forEach(line=>{const parts=line.split('|');if(parts.length>1)add(parts[0].trim(),parts.slice(1).join('|').trim())});ids.slice(1).forEach(id=>{const other=data.get(id);add(other.name,other.url);other.signals.split(/\r?\n/).forEach(line=>{const parts=line.split('|');if(parts.length>1)add(parts[0].trim()||other.name,parts.slice(1).join('|').trim())});if(!base.logo&&other.logo)base.logo=other.logo;if(!base.group&&other.group)base.group=other.group;removed.add(id)});const unique=[...new Map(sigs.map(x=>[normalizeMatch(x.url),x])).values()];base.url=unique[0]?.url||'';base.signals=unique.slice(1).map((x,i)=>`${x.name||`Señal ${i+2}`} | ${x.url}`).join('\n')});
 rows.forEach(row=>{const d=data.get(row.dataset.rowId);if(removed.has(d.id)){row.remove();return}row.querySelector('[data-field="url"]').value=d.url;row.querySelector('[data-field="logo"]').value=d.logo;row.querySelector('[data-field="group"]').value=d.group;row.querySelector('[data-field="signals"]').value=d.signals||''});
 closeModal();collectEditor();toast('Canales unidos; las señales alternativas quedaron guardadas.','success');
}
function applyEditorSearch(){const input=$('#editorChannelSearch'),tbody=$('#editorRows');if(!tbody)return;const q=(input?.value||'').trim().toLocaleLowerCase('es');let visible=0;const rows=tbody.querySelectorAll('tr');rows.forEach(row=>{if(!row.dataset.searchIndex||row.dataset.searchDirty==='1'){row.dataset.searchIndex=Array.from(row.querySelectorAll('input:not([type=checkbox]),textarea')).map(el=>el.value||'').join(' ').toLocaleLowerCase('es');delete row.dataset.searchDirty}const reviewMatch=!signalReviewActive||signalReviewIds.has(row.dataset.rowId);const match=reviewMatch&&(!q||row.dataset.searchIndex.includes(q));row.hidden=!match;if(match)visible++});const count=$('#editorSearchCount');if(count)count.textContent=q?`${visible} de ${rows.length} canales`:`${rows.length} canales`;const empty=$('#editorSearchEmpty');if(empty)empty.remove();if(q&&visible===0){const wrap=$('.editor-table-wrap');if(wrap){const note=document.createElement('p');note.id='editorSearchEmpty';note.className='editor-search-empty';note.textContent='No hay canales que coincidan con esa búsqueda.';wrap.append(note)}}} 
function editorRow(c,i){const sigs=(c.signals||[]).filter(s=>s.url && s.url!==(c.url||'')).map(s=>`${s.name||'Señal'} | ${s.url}`).join('\n');return `<tr class="editor-channel-card" data-row-id="${c.id}"><td class="select-col" aria-hidden="true"><input type="checkbox" data-row-select tabindex="-1" aria-label="Estado de selección de ${safe(c.name)}"></td><td class="field-name" data-label="Nombre del canal"><label>Nombre<input data-field="name" value="${safe(c.name)}" aria-label="Nombre del canal"></label></td><td class="field-url" data-label="Señal principal"><label>URL de señal principal<input data-field="url" value="${safe(c.url||c.signals?.[0]?.url||'')}" placeholder="https://…" aria-label="URL de señal principal"></label></td><td class="field-group" data-label="Categoría principal"><label>Categoría principal<input data-field="group" value="${safe(c.group||'Sin categoría')}" aria-label="Categoría principal" placeholder="Entretenimiento"></label></td><td class="field-categories" data-label="Categorías adicionales"><label>Categorías adicionales<input data-field="categories" value="${safe((c.categories||[]).join(', '))}" aria-label="Categorías adicionales" placeholder="Música, Noticias"><small>Separadas por comas</small></label></td><td class="field-language" data-label="Idioma"><label>Idioma<input data-field="language" value="${safe(c.language||'')}" aria-label="Idioma" placeholder="Español"></label></td><td class="field-country" data-label="País"><label>País<input data-field="country" value="${safe(c.country||'')}" aria-label="País" placeholder="Colombia"></label></td><td class="field-logo" data-label="Logo"><label>Logo<div class="logo-editor"><input data-field="logo" value="${safe(c.logo||'')}" placeholder="URL del logo" aria-label="URL del logo"><button type="button" class="tiny-btn" data-logo-search="${safe(c.name)}" title="Buscar logo en la web">Buscar</button></div></label></td><td class="field-signals" data-label="Señales alternativas"><label>Señales alternativas<textarea data-field="signals" rows="2" placeholder="Señal HD | https://…&#10;Señal 3 | https://…">${safe(sigs)}</textarea><small>Una señal por línea: Nombre | URL</small></label></td><td class="field-actions"><button type="button" class="bulk-row-select-btn" data-bulk-row-toggle="${c.id}" aria-pressed="false">Seleccionar</button><div class="row-actions"><button class="tiny-btn" data-move-up="${c.id}" title="Subir canal" aria-label="Subir canal">↑</button><button class="tiny-btn" data-move-down="${c.id}" title="Bajar canal" aria-label="Bajar canal">↓</button><button class="tiny-btn" data-duplicate-row="${c.id}" title="Duplicar canal" aria-label="Duplicar canal">⧉</button><button class="row-delete" data-delete-row="${c.id}" aria-label="Eliminar canal">×</button></div></td></tr>`}
function collectEditor(){const p=db.playlists.find(p=>p.id===activeEditor);if(!p)return;pushEditorUndo(p);const name=$('#editorPlaylistName');if(name)p.name=name.value.trim()||'Mi lista';const rows=$$('#editorRows tr');p.channels=rows.map(tr=>{const old=p.channels.find(c=>c.id===tr.dataset.rowId)||{id:tr.dataset.rowId||id(),signals:[]};const val=k=>tr.querySelector(`[data-field="${k}"]`)?.value.trim()||'';const url=val('url');const alternatives=val('signals').split(/\r?\n/).map(line=>{const parts=line.split('|');return {id:id(),name:(parts.shift()||'Señal alternativa').trim(),url:parts.join('|').trim()}}).filter(s=>s.url);const signals=[...(url?[{id:old.signals?.[0]?.id||id(),name:'Señal principal',url}]:[]),...alternatives];return {...old,name:val('name')||'Canal sin nombre',url,group:val('group')||'Sin categoría',categories:val('categories').split(',').map(x=>x.trim()).filter(Boolean),language:val('language'),country:val('country'),logo:val('logo'),signals}});save();refresh();renderEditorWorkspace(p.id);toast('Cambios guardados.','success')}
function exportPlaylist(pid,mode){const p=db.playlists.find(p=>p.id===pid);if(!p)return;if(!mode){openModal('Exportar lista','ELIGE CÓMO ORGANIZAR LAS SEÑALES',`<div class="choice-row"><button class="choice-card" data-export-mode="grouped" data-export-playlist="${safe(p.id)}"><strong>Un canal con varias señales</strong><small>Conserva las señales alternativas dentro del mismo canal. TesitoTV las reconocerá al volver a importar el M3U.</small></button><button class="choice-card" data-export-mode="separate" data-export-playlist="${safe(p.id)}"><strong>Una entrada por señal</strong><small>Exporta cada señal como canal separado, aunque pertenezcan al mismo canal.</small></button></div><div class="modal-footer"><button class="secondary-btn" data-modal-action="close">Cancelar</button></div>`);return}closeModal();const blob=new Blob([TesitoPlaylist.serialize(p,mode)],{type:'audio/x-mpegurl;charset=utf-8'});download(blob,`${slug(p.name)}-${mode==='grouped'?'senales-agrupadas':'senales-separadas'}.m3u`);toast(mode==='grouped'?'Lista exportada con señales agrupadas.':'Lista exportada con señales separadas.','success')}
function download(blob,name){const a=document.createElement('a');const u=URL.createObjectURL(blob);a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500)}function slug(s){return String(s||'tesitotv').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'tesitotv'}
function findChannel(cid){return allChannels().find(c=>c.id===cid)}function playChannel(cid){const c=findChannel(cid);if(!c)return;const url=c.url||c.signals?.[0]?.url;if(!url){toast('Este canal todavía no tiene una dirección de reproducción.','error');return}activeChannelId=cid;recordHistory(c,{name:'Señal principal',url});$('#playerDock').classList.remove('hidden');const signalSel=$('#signalSelect');const sigs=(c.signals&&c.signals.length?c.signals:[{name:'Señal principal',url:c.url}]).filter(s=>s.url);signalSel.innerHTML=sigs.map((s,i)=>`<option value="${i}">${safe(s.name||'Señal '+(i+1))}</option>`).join('');$('#signalPicker').style.display=sigs.length>1?'flex':'none';signalSel.dataset.channelId=cid;$('#nowTitle').textContent=c.name;$('#nowSubtitle').textContent=`${c.playlistName||'Canal individual'} · ${c.group||'Sin categoría'} · ${sigs.length} señal${sigs.length===1?'':'es'}${currentProgram(c)?' · Ahora: '+currentProgram(c):''}`;$('#overlayTitle').textContent=c.name;$('#overlayMessage').textContent='Conectando con la señal…';$('#upNextList').innerHTML='';renderUpNext();TesitoPlayer.play(url,c);}
function renderUpNext(){const root=$('#upNextList');if(!root)return;let ch=allChannels();if(activeChannelId){const index=ch.findIndex(c=>c.id===activeChannelId);if(index>0)ch=[...ch.slice(index),...ch.slice(0,index)]}root.innerHTML=ch.slice(0,80).map(c=>`<div class="up-next-item ${c.id===activeChannelId?'active':''}" data-play="${c.id}"><div class="up-next-logo">${c.logo?`<img src="${safe(c.logo)}" alt="" onerror="this.remove()">`:safe(c.name.slice(0,2).toUpperCase())}</div><div><strong>${safe(c.name)}</strong><small>${safe(c.group||c.playlistName||'Canal')}</small></div></div>`).join('')||'<p class="muted small" style="padding:12px">Añade canales para verlos aquí.</p>'}
function toggleFav(cid){if(db.favorites.includes(cid))db.favorites=db.favorites.filter(x=>x!==cid);else db.favorites.push(cid);save();refresh()}
function copyChannel(cid){const c=findChannel(cid);if(!c)return;const url=c.url||c.signals?.[0]?.url;if(!url){toast('Este canal no tiene URL todavía.','error');return}if(navigator.clipboard?.writeText)navigator.clipboard.writeText(url).then(()=>toast('Enlace del canal copiado.','success')).catch(()=>prompt('Copia el enlace del canal:',url));else prompt('Copia el enlace del canal:',url)}

function exportBackup(){const payload={app:'TesitoTV',version:1,exportedAt:new Date().toISOString(),data:db};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),'tesitotv-copia-'+new Date().toISOString().slice(0,10)+'.json');toast('Copia de seguridad descargada.','success')}
function restoreBackup(text){let parsed;try{parsed=JSON.parse(text)}catch(e){toast('El archivo no contiene JSON válido.','error');return false}const incoming=parsed?.data||parsed;if(!incoming||!Array.isArray(incoming.playlists)){toast('Este archivo no parece una copia de TesitoTV.','error');return false}if(!confirm('Restaurar reemplazará las listas, favoritos y preferencias actuales de este navegador. ¿Continuar?'))return false;db={playlists:incoming.playlists.map(p=>({...p,id:p.id||id(),name:String(p.name||'Lista restaurada'),channels:Array.isArray(p.channels)?p.channels.map(c=>({...c,id:c.id||id(),name:String(c.name||'Canal sin nombre'),url:String(c.url||''),group:String(c.group||'Sin categoría'),categories:Array.isArray(c.categories)?c.categories:[],language:String(c.language||''),country:String(c.country||''),logo:String(c.logo||''),signals:Array.isArray(c.signals)?c.signals:[]})):[]})),favorites:Array.isArray(incoming.favorites)?incoming.favorites:[],settings:{...{theme:'dark',view:'grid',sidebar:true},...(incoming.settings||{})}};save();document.body.classList.toggle('light',db.settings.theme==='light');activeEditor=db.playlists[0]?.id||null;refresh();renderEditorWorkspace(activeEditor);toast('Copia restaurada correctamente.','success');return true}
function normalizeMatch(v){return String(v||'').trim().toLowerCase().replace(/[\s._\-()[\]{}]+/g,'').replace(/\/+$/,'')}
function maintenanceData(){const channels=db.playlists.flatMap(p=>(p.channels||[]).map(c=>({...c,playlistName:p.name,playlistId:p.id})));const signalRefs=[];channels.forEach(c=>{const urls=[{name:'Principal',url:c.url},...(c.signals||[]).map((x,i)=>({name:x.name||`Alternativa ${i+1}`,url:x.url}))];const seenInChannel=new Set();urls.forEach(sig=>{const key=normalizeMatch(sig.url);if(sig.url&&!seenInChannel.has(key)){seenInChannel.add(key);signalRefs.push({...sig,channelName:c.name,channelId:c.id,playlistName:c.playlistName,playlistId:c.playlistId})}})});const byUrl=new Map();signalRefs.forEach(x=>{const k=normalizeMatch(x.url);if(!byUrl.has(k))byUrl.set(k,[]);byUrl.get(k).push(x)});const duplicateSignals=[...byUrl.values()].filter(g=>g.length>1);const byName=new Map();channels.forEach(c=>{const k=normalizeMatch(c.name);if(k){if(!byName.has(k))byName.set(k,[]);byName.get(k).push(c)}});const duplicateNames=[...byName.values()].filter(g=>g.length>1);const missing=channels.filter(c=>!(c.url||c.signals?.some(s=>s.url)));const invalid=channels.filter(c=>[c.url,...(c.signals||[]).map(s=>s.url)].filter(Boolean).some(u=>!/^https?:\/\//i.test(u)));return {channels,signalRefs,duplicateSignals,duplicateNames,missing,invalid,multi:channels.filter(c=>(c.signals||[]).filter(s=>s.url).length>1),noLogo:channels.filter(c=>!c.logo)}}
function diagnostics(){const d=maintenanceData();const dupHtml=d.duplicateSignals.length?d.duplicateSignals.map((g,i)=>`<div class="maintenance-group"><strong>URL repetida ${i+1} <span class="maintenance-count">${g.length} usos</span></strong><ul>${g.map(x=>`<li><b>${safe(x.channelName)}</b> <span class="muted">(${safe(x.playlistName)} · ${safe(x.name)})</span><br><code>${safe(x.url)}</code></li>`).join('')}</ul><button class="small-btn" data-copy-url="${safe(g[0].url)}">Copiar URL</button></div>`).join(''):'<p class="success-note">No se encontraron URLs de señal repetidas.</p>';const namesHtml=d.duplicateNames.length?d.duplicateNames.map((g,i)=>`<div class="maintenance-group"><strong>Nombre parecido ${i+1} <span class="maintenance-count">${g.length} canales</span></strong><ul>${g.map(x=>`<li><b>${safe(x.name)}</b> <span class="muted">(${safe(x.playlistName)})</span> — ${safe(x.url||'sin URL')}</li>`).join('')}</ul><p class="field-hint">Puede ser un duplicado o dos canales legítimos con el mismo nombre. Revisa antes de borrar.</p></div>`).join(''):'<p class="success-note">No se encontraron nombres de canal repetidos.</p>';const body=`<div class="diagnostic-grid"><div class="diagnostic-stat"><strong>${d.channels.length}</strong><span>Canales</span></div><div class="diagnostic-stat"><strong>${d.duplicateSignals.length}</strong><span>Grupos de URLs repetidas</span></div><div class="diagnostic-stat"><strong>${d.duplicateNames.length}</strong><span>Grupos de nombres repetidos</span></div><div class="diagnostic-stat"><strong>${d.missing.length}</strong><span>Sin señal</span></div><div class="diagnostic-stat"><strong>${d.invalid.length}</strong><span>URLs sospechosas</span></div><div class="diagnostic-stat"><strong>${d.noLogo.length}</strong><span>Sin logo</span></div></div><p class="field-hint">Se comparan URLs normalizadas (mayúsculas/minúsculas, espacios y barras finales). Dos URLs distintas pueden apuntar al mismo contenido, y dos entradas con la misma URL no siempre son un error: revisa antes de eliminar.</p><h3>Señales con la misma URL</h3>${dupHtml}<h3>Canales con nombres repetidos</h3>${namesHtml}<h3>Canales sin señal o URL sospechosa</h3>${d.missing.length||d.invalid.length?`<ul class="diagnostic-list">${d.missing.slice(0,50).map(c=>`<li><b>${safe(c.name)}</b> — ${safe(c.playlistName)}: no tiene URL de señal.</li>`).join('')}${d.invalid.slice(0,50).map(c=>`<li><b>${safe(c.name)}</b> — contiene una URL que no comienza por http:// o https://.</li>`).join('')}</ul>`:'<p class="success-note">No se encontraron canales sin señal ni URLs con formato inesperado.</p>'}<div class="modal-footer"><button class="primary-btn" data-modal-action="close">Cerrar</button></div>`;openModal('Diagnóstico de biblioteca','MANTENIMIENTO',`<div class="modal-form">${body}</div>`)}
function comparePlaylists(){if(db.playlists.length<2){toast('Necesitas al menos dos listas para compararlas.','error');return}const opts=db.playlists.map(p=>`<option value="${safe(p.id)}">${safe(p.name)} (${p.channels.length})</option>`).join('');openModal('Comparar listas','COMPARADOR M3U',`<div class="modal-form"><p class="field-hint">Compara por URL de señal normalizada. Los resultados no modifican ninguna lista.</p><label>Lista base<select id="compareA">${opts}</select></label><label>Comparar con<select id="compareB">${opts}</select></label><button class="primary-btn" id="runCompare">Comparar ahora</button><div id="compareResults"></div></div>`)}
function runCompare(){const a=db.playlists.find(p=>p.id===$('#compareA').value),b=db.playlists.find(p=>p.id===$('#compareB').value);if(!a||!b||a.id===b.id){toast('Elige dos listas diferentes.','error');return}const key=c=>normalizeMatch(c.url||c.signals?.find(s=>s.url)?.url||c.name);const ma=new Map(a.channels.map(c=>[key(c),c])),mb=new Map(b.channels.map(c=>[key(c),c]));const added=b.channels.filter(c=>!ma.has(key(c))),removed=a.channels.filter(c=>!mb.has(key(c))),shared=b.channels.filter(c=>ma.has(key(c))&&ma.get(key(c)).name!==c.name);$('#compareResults').innerHTML=`<div class="diagnostic-grid"><div class="diagnostic-stat"><strong>${added.length}</strong><span>Nuevos en ${safe(b.name)}</span></div><div class="diagnostic-stat"><strong>${removed.length}</strong><span>Solo en ${safe(a.name)}</span></div><div class="diagnostic-stat"><strong>${shared.length}</strong><span>Misma clave, nombre cambiado</span></div></div><h3>Añadidos</h3>${comparisonList(added)}<h3>Ya no aparecen</h3>${comparisonList(removed)}<h3>Posibles cambios de nombre</h3>${comparisonList(shared)}`;function comparisonList(arr){return arr.length?`<ul class="diagnostic-list">${arr.slice(0,100).map(c=>`<li><b>${safe(c.name)}</b> — ${safe(c.url||c.signals?.[0]?.url||'sin URL')}</li>`).join('')}</ul>${arr.length>100?`<p class="field-hint">Mostrando 100 de ${arr.length}.</p>`:''}`:'<p class="field-hint">Ninguno.</p>'}}

function selectedEditorRows(){return $$('[data-row-select]:checked').map(x=>x.closest('tr')).filter(Boolean)}
function updateBulkSelectionBar(){const rows=selectedEditorRows();$$('#editorRows tr[data-row-id]').forEach(row=>{const checked=!!row.querySelector('[data-row-select]')?.checked;row.classList.toggle('bulk-row-selected',checked);const btn=row.querySelector('.bulk-row-select-btn');if(btn){btn.setAttribute('aria-pressed',String(checked));btn.textContent=checked?'✓ Seleccionado':'Seleccionar'}});const count=$('#bulkSelectionCount'),edit=$('#editSelectedBulk'),select=$('#selectVisibleBulk');if(count)count.textContent=rows.length?`${rows.length} canal${rows.length===1?' seleccionado':'es seleccionados'}`:'Marca la casilla de cada canal que quieras modificar.';if(edit){edit.disabled=!rows.length;edit.textContent=rows.length?`Editar ${rows.length} seleccionado${rows.length===1?'':'s'}`:'Editar seleccionados'}if(select){const visible=$$('#editorRows tr').filter(r=>!r.hidden);select.textContent=visible.length&&visible.every(r=>r.querySelector('[data-row-select]')?.checked)?'Quitar selección':'Seleccionar todos'}const toggle=$('#bulkEditor');if(toggle){toggle.setAttribute('aria-pressed',String(bulkSelectionMode));toggle.textContent=bulkSelectionMode?'× Salir de edición múltiple':'☑ Edición múltiple'}}
function exitBulkSelectionMode(){bulkSelectionMode=false;const ws=$('#editorWorkspace');ws?.classList.remove('multi-select-mode');$('#bulkSelectionBar')?.classList.add('hidden');$$('[data-row-select],#selectAllEditorRows').forEach(x=>x.checked=false);const toggle=$('#bulkEditor');if(toggle){toggle.textContent='☑ Edición múltiple';toggle.setAttribute('aria-pressed','false')}}
function openBulkEditModal(){const rows=selectedEditorRows();if(!rows.length){toast('Primero selecciona al menos un canal.');return}openModal('Editar canales seleccionados','EDICIÓN MÚLTIPLE',`<div class="modal-form bulk-edit-form"><p>Los cambios se aplicarán a <b>${rows.length} canales</b>. Deja un campo vacío para conservar su valor actual.</p><div class="bulk-edit-grid"><label>Categoría principal<input id="bulkGroup" placeholder="Ej. Música"></label><label>Categorías adicionales<input id="bulkCategories" placeholder="Música, Noticias"><small>Separadas por comas</small></label><label>Idioma<input id="bulkLanguage" placeholder="Ej. Español"></label><label>País<input id="bulkCountry" placeholder="Ej. Colombia"></label></div><div class="bulk-edit-divider"></div><p class="field-hint">También puedes modificar los nombres de los canales:</p><label>Texto para añadir al nombre<input id="bulkPrefix" placeholder="Prefijo opcional"></label><div class="bulk-edit-grid"><label>Buscar texto<input id="bulkFind" placeholder="Texto actual"></label><label>Reemplazar por<input id="bulkReplace" placeholder="Texto nuevo"></label></div><div class="modal-footer"><button class="small-btn" data-modal-action="close">Cancelar</button><button class="primary-btn" id="applyBulkEditor">Aplicar cambios</button></div></div>`);window.__bulkRows=rows.map(r=>r.dataset.rowId)}
function bulkEditor(rowId){if(!rowId&&bulkSelectionMode){exitBulkSelectionMode();return}if(!bulkSelectionMode){bulkSelectionMode=true;$('#editorWorkspace').classList.add('multi-select-mode');$('#bulkSelectionBar')?.classList.remove('hidden')}if(rowId){const row=$(`#editorRows tr[data-row-id="${CSS.escape(rowId)}"]`),cb=row?.querySelector('[data-row-select]');if(cb)cb.checked=!cb.checked}updateBulkSelectionBar()}
function applyBulkEditor(){const ids=new Set(window.__bulkRows||[]),rows=$$('#editorRows tr').filter(r=>ids.has(r.dataset.rowId));const value=id=>$('#'+id)?.value.trim()||'',group=value('bulkGroup'),categories=value('bulkCategories'),language=value('bulkLanguage'),country=value('bulkCountry'),prefix=$('#bulkPrefix')?.value||'',find=$('#bulkFind')?.value||'',replace=$('#bulkReplace')?.value||'';rows.forEach(r=>{if(group)r.querySelector('[data-field="group"]').value=group;if(categories)r.querySelector('[data-field="categories"]').value=categories;if(language)r.querySelector('[data-field="language"]').value=language;if(country)r.querySelector('[data-field="country"]').value=country;if(prefix)r.querySelector('[data-field="name"]').value=prefix+r.querySelector('[data-field="name"]').value;if(find)r.querySelector('[data-field="name"]').value=r.querySelector('[data-field="name"]').value.split(find).join(replace)});closeModal();exitBulkSelectionMode();toast(`Cambios aplicados a ${rows.length} canales. Pulsa Guardar cambios para conservarlos.`,'success')}
function cleanupEditor(){const rows=$$('#editorRows tr');const empty=rows.filter(r=>!r.querySelector('[data-field="url"]').value.trim()&&!r.querySelector('[data-field="signals"]').value.trim());const names=new Map();rows.forEach(r=>{const n=normalizeChannelName(r.querySelector('[data-field="name"]').value);if(n){if(!names.has(n))names.set(n,[]);names.get(n).push(r)}});const duplicateGroups=[...names.values()].filter(g=>g.length>1);openModal('Limpieza de lista','REVISIÓN SEGURA',`<div class="modal-form"><div class="diagnostic-grid"><div class="diagnostic-stat"><strong>${empty.length}</strong><span>Filas sin señal</span></div><div class="diagnostic-stat"><strong>${duplicateGroups.length}</strong><span>Grupos de nombres repetidos</span></div><div class="diagnostic-stat"><strong>${rows.filter(r=>{const u=r.querySelector('[data-field="url"]').value.trim();return u&&!/^https?:\/\//i.test(u)}).length}</strong><span>URLs sospechosas</span></div></div><p class="field-hint">No se elimina nada automáticamente. Puedes quitar las filas sin señal, pero revisa antes: quizá estés editando canales que aún no has terminado.</p><button class="primary-btn" id="removeEmptyEditorRows" ${empty.length?'':'disabled'}>Eliminar ${empty.length} filas sin señal</button><div class="modal-footer"><button class="small-btn" data-modal-action="close">Cerrar</button></div></div>`);window.__emptyEditorIds=empty.map(r=>r.dataset.rowId)}
function removeEmptyEditorRows(){const ids=new Set(window.__emptyEditorIds||[]);if(!ids.size)return;pushEditorUndo(db.playlists.find(p=>p.id===activeEditor));$$('#editorRows tr').forEach(r=>{if(ids.has(r.dataset.rowId))r.remove()});closeModal();toast(`Se quitaron ${ids.size} filas. Pulsa Guardar cambios para conservar la limpieza.`,'success')}
async function testEditorSignals(){
 const rows=$$('#editorRows tr');if(!rows.length){toast('No hay canales que comprobar.','error');return}
 signalReviewIds=new Set();signalReviewActive=false;rows.forEach(row=>{row.classList.remove('signal-check-failed','signal-check-unknown','signal-check-ok');row.dataset.signalFailed='';row.dataset.signalUnknown='' });
 // Check each unique URL once, then apply its result to every row that uses it.
 const byUrl=new Map();rows.forEach(row=>{const primary=row.querySelector('[data-field="url"]')?.value.trim()||'';const alt=(row.querySelector('[data-field="signals"]')?.value||'').split(/\r?\n/).map(line=>line.split('|').slice(1).join('|').trim()).filter(Boolean);[...new Set([primary,...alt].filter(Boolean))].forEach(url=>{const key=normalizeMatch(url);if(!byUrl.has(key))byUrl.set(key,{url,refs:[]});byUrl.get(key).refs.push({row,rowId:row.dataset.rowId})})});
 const tasks=[...byUrl.values()];if(!tasks.length){toast('No hay URLs para comprobar.','error');return}
 const status=toast(`Comprobando señales únicas en segundo plano… 0/${tasks.length}`,'progress',0);status.setAttribute('role','status');status.setAttribute('aria-live','polite');let next=0,checked=0,failed=0,unknown=0;
 async function worker(){while(true){const taskIndex=next++;if(taskIndex>=tasks.length)return;const task=tasks[taskIndex];let result='unknown';let parsed;try{parsed=new URL(task.url)}catch(e){}if(!parsed||!/^https?:$/.test(parsed.protocol)){result='failed'}else{const ctrl=new AbortController();let timer;try{timer=setTimeout(()=>ctrl.abort(),2200);await fetch(task.url,{method:'GET',mode:'no-cors',cache:'no-store',signal:ctrl.signal});result='unknown'}catch(e){result=e.name==='AbortError'?'unknown':'failed'}finally{if(timer)clearTimeout(timer)}}for(const ref of task.refs){if(result==='failed'){ref.row.dataset.signalFailed='1';ref.row.classList.remove('signal-check-unknown');ref.row.classList.add('signal-check-failed');signalReviewIds.add(ref.rowId)}else if(ref.row.dataset.signalFailed!=='1'){ref.row.dataset.signalUnknown='1';ref.row.classList.add('signal-check-unknown')}}if(result==='failed')failed++;else unknown++;checked++;status.textContent=`Comprobando señales únicas en segundo plano… ${checked}/${tasks.length}`;status.style.setProperty('--progress',`${Math.round(checked/tasks.length*100)}%`)}}
 await Promise.all(Array.from({length:Math.min(4,tasks.length)},()=>worker()));
 const reviewBtn=$('#reviewFailedSignals');if(reviewBtn){reviewBtn.classList.toggle('hidden',signalReviewIds.size===0);reviewBtn.textContent=`Revisión de señales (${signalReviewIds.size})`;}
 status.className='toast '+(failed===0?'success':'error');status.textContent=`Revisión terminada: ${tasks.length} URLs únicas · ${failed} solicitudes fallidas · ${unknown} sin confirmar. ${failed?'Puedes abrir Revisión de señales para corregir o quitar los canales rojos.':'No se detectaron fallos de solicitud; algunas señales pueden quedar sin confirmar por restricciones del navegador.'}`;status.style.setProperty('--progress','100%');status.title='Rojo: URL inválida o solicitud fallida. Ámbar: solicitud sin confirmación concluyente; el timeout no se considera fallo.';setTimeout(()=>status.remove(),13000);
}
function showStats(){const d=maintenanceData(),cats=new Map();d.channels.forEach(c=>{const g=c.group||'Sin categoría';cats.set(g,(cats.get(g)||0)+1)});const top=[...cats.entries()].sort((a,b)=>b[1]-a[1]).slice(0,12);openModal('Estadísticas de biblioteca','TESITOTV',`<div class="modal-form"><div class="diagnostic-grid"><div class="diagnostic-stat"><strong>${d.channels.length}</strong><span>Canales</span></div><div class="diagnostic-stat"><strong>${d.signalRefs.length}</strong><span>Señales únicas por canal</span></div><div class="diagnostic-stat"><strong>${cats.size}</strong><span>Categorías</span></div><div class="diagnostic-stat"><strong>${db.playlists.length}</strong><span>Listas</span></div><div class="diagnostic-stat"><strong>${db.favorites.length}</strong><span>Favoritos</span></div><div class="diagnostic-stat"><strong>${d.duplicateNames.length}</strong><span>Grupos de nombres repetidos</span></div></div><h3>Categorías más grandes</h3><ul class="diagnostic-list">${top.map(([name,n])=>`<li><b>${safe(name)}</b> — ${n} canales</li>`).join('')||'<li>Aún no hay categorías.</li>'}</ul><div class="modal-footer"><button class="primary-btn" data-modal-action="close">Cerrar</button></div></div>`)}
function importEPG(file){file.text().then(txt=>{try{const xml=new DOMParser().parseFromString(txt,'application/xml');if(xml.querySelector('parsererror'))throw Error('XML inválido');const channels=[...xml.querySelectorAll('channel')].map(c=>({id:c.getAttribute('id')||'',name:c.querySelector('display-name')?.textContent?.trim()||''}));const programs=[...xml.querySelectorAll('programme')].map(p=>({channel:p.getAttribute('channel')||'',start:p.getAttribute('start')||'',stop:p.getAttribute('stop')||'',title:p.querySelector('title')?.textContent?.trim()||''})).filter(x=>x.title);db.epg={channels,programs};save();toast(`Guía cargada: ${programs.length} programas. La coincidencia automática se aplicará si el ID/nombre coincide.`,'success')}catch(e){toast('No se pudo leer el XMLTV. Usa un XMLTV sin comprimir (.xml).','error')}})}
function currentProgram(c){if(!db.epg?.programs)return '';const now=Date.now(),norm=normalizeChannelName(c.name);const matchIds=(db.epg.channels||[]).filter(x=>normalizeChannelName(x.name)===norm).map(x=>x.id);const prog=db.epg.programs.find(x=>(matchIds.includes(x.channel)||normalizeChannelName(x.channel)===norm)&&Date.parse(x.start.slice(0,4)+'-'+x.start.slice(4,6)+'-'+x.start.slice(6,8)+'T'+x.start.slice(8,10)+':'+x.start.slice(10,12)+':'+x.start.slice(12,14)+'Z')<=now&&Date.parse(x.stop.slice(0,4)+'-'+x.stop.slice(4,6)+'-'+x.stop.slice(6,8)+'T'+x.stop.slice(8,10)+':'+x.stop.slice(10,12)+':'+x.stop.slice(12,14)+'Z')>now);return prog?.title||''}
function githubGuide(){openModal('Publicar una lista en GitHub','GUÍA PASO A PASO',`<div class="modal-form"><p class="field-hint">Publica únicamente listas que tengas derecho a compartir. No subas credenciales, tokens, suscripciones privadas ni enlaces que identifiquen tu cuenta.</p><ol style="padding-left:20px;line-height:1.8;color:#d1d2d8;font-size:12px"><li>Entra en <a style="color:var(--accent)" href="https://github.com/new" target="_blank" rel="noopener">github.com/new</a> e inicia sesión.</li><li>Crea un repositorio. Si la lista es pública, cualquiera podrá verla y copiarla.</li><li>En el repositorio, pulsa <b>Add file → Create new file</b>.</li><li>Escribe un nombre como <code>mi-lista.m3u</code> y pega el contenido exportado desde TesitoTV.</li><li>Pulsa <b>Commit changes</b> para guardar el archivo.</li><li>Abre el archivo y usa <b>Raw</b> para ver su contenido sin formato; copia esa dirección si tu reproductor admite listas remotas.</li></ol><p class="field-hint">GitHub Pages aloja páginas web estáticas; no actúa como proxy de los canales. Las URLs de la lista siguen dependiendo de sus servidores originales y de CORS.</p><div class="modal-footer"><button class="primary-btn" data-modal-action="close">Entendido</button></div></div>`)}
const MV_PROFILES_KEY='tesitotv.multiview.profiles.v1';
function getMvProfiles(){try{const p=JSON.parse(localStorage.getItem(MV_PROFILES_KEY)||'[]');return Array.isArray(p)?p.filter(x=>x&&typeof x.name==='string'&&Array.isArray(x.channels)):[]}catch(e){return []}}
function refreshMvProfiles(selected=''){const el=$('#mvProfileSelect');if(!el)return;const profiles=getMvProfiles();el.innerHTML='<option value="">Elegir perfil…</option>'+profiles.map((p,i)=>`<option value="${i}">${safe(p.name)}</option>`).join('');if(selected!==''&&profiles[Number(selected)])el.value=String(selected)}
function saveMvProfile(){const box=$('#mvProfileSaveBox'),input=$('#mvProfileName');if(box)box.classList.remove('hidden');if(input){input.value='';input.focus()}}
function confirmSaveMvProfile(){const input=$('#mvProfileName'),clean=(input?.value||'').trim();if(!clean){toast('Escribe un nombre para el perfil.','error');input?.focus();return}const channels=Array.from({length:mvCount},(_,i)=>document.querySelector(`[data-mv-select="${i}"]`)?.value||'');const liveAudio=Array.from({length:mvCount},(_,i)=>document.querySelector(`[data-mv-video="${i}"]`)?.muted!==false);const profile={name:clean,count:mvCount,channels,audio:$('#mvRecordAudio')?.value||'none',liveAudio,updatedAt:new Date().toISOString()};const profiles=getMvProfiles();const existing=profiles.findIndex(p=>p.name.toLocaleLowerCase()===clean.toLocaleLowerCase());if(existing>=0){profiles[existing]=profile;localStorage.setItem(MV_PROFILES_KEY,JSON.stringify(profiles));refreshMvProfiles(String(existing));toast(`Perfil «${clean}» actualizado.`,'success')}else{profiles.push(profile);localStorage.setItem(MV_PROFILES_KEY,JSON.stringify(profiles));refreshMvProfiles(String(profiles.length-1));toast(`Perfil «${clean}» guardado.`,'success')}$('#mvProfileSaveBox')?.classList.add('hidden')}
function loadMvProfile(){const sel=$('#mvProfileSelect');if(!sel||sel.value===''){toast('Selecciona un perfil guardado.','error');return}const p=getMvProfiles()[Number(sel.value)];if(!p)return;stopAllMv();mvCount=Math.max(1,Math.min(4,Number(p.count)||p.channels.length||1));renderMultiview();const audio=$('#mvRecordAudio');if(audio&&['none','0','1','2','3','all'].includes(p.audio))audio.value=p.audio;(p.channels||[]).slice(0,mvCount).forEach((cid,i)=>{const channel=findChannel(cid);const control=document.querySelector(`[data-mv-select="${i}"]`);if(control&&channel){control.value=cid;playMvSlot(i,cid);if(p.liveAudio&&p.liveAudio[i]===false){const v=document.querySelector(`[data-mv-video="${i}"]`),b=document.querySelector(`[data-mv-audio="${i}"]`);if(v&&b){v.muted=false;b.textContent='🔊 Audio';b.classList.add('active')}}}});$('#mvStatus').textContent=`Perfil «${p.name}» cargado. Las señales dependen de su disponibilidad.`;toast(`Perfil «${p.name}» cargado.`,'success')}
function deleteMvProfile(){const sel=$('#mvProfileSelect');if(!sel||sel.value===''){toast('Selecciona el perfil que quieres eliminar.','error');return}const profiles=getMvProfiles(),idx=Number(sel.value),p=profiles[idx];if(!p)return;if(!confirm(`¿Eliminar el perfil «${p.name}»? Los canales y las listas no se eliminarán.`))return;profiles.splice(idx,1);localStorage.setItem(MV_PROFILES_KEY,JSON.stringify(profiles));refreshMvProfiles();toast('Perfil eliminado.','success')}
function stopMvSlot(i){const x=mvPlayers[i];if(!x)return;if(x.hls){try{x.hls.destroy()}catch(e){}x.hls=null}const v=document.querySelector(`[data-mv-video="${i}"]`);if(v){v.pause();v.removeAttribute('src');v.load();v.muted=true}mvPlayers[i]={hls:null,channelId:'',state:'EN ESPERA'};const st=document.querySelector(`[data-mv-state="${i}"]`);if(st){st.textContent='EN ESPERA';st.classList.remove('error')}const ph=document.querySelector(`[data-mv-placeholder="${i}"]`);if(ph)ph.classList.remove('hidden')}
function stopAllMv(){for(let i=0;i<4;i++)stopMvSlot(i);const st=$('#mvStatus');if(st)st.textContent='Todas las pantallas detenidas.'}
function renderMultiview(){const root=$('#multiviewGrid');if(!root)return;root.dataset.count=String(mvCount);$$('[data-mv-count]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.mvCount)===mvCount));const channels=allChannels();const options='<option value="">— Selecciona un canal —</option>'+channels.map(c=>`<option value="${safe(c.id)}">${safe(c.name)} · ${safe(c.playlistName||'Lista')}</option>`).join('');root.innerHTML=Array.from({length:mvCount},(_,i)=>`<article class="mv-screen" draggable="true" data-mv-slot="${i}" title="Arrastra esta pantalla sobre otra para intercambiar canales"><div class="mv-head"><span class="mv-drag" aria-hidden="true" title="Arrastrar para cambiar de posición">⠿</span><label>PANTALLA ${i+1}</label><select data-mv-select="${i}" aria-label="Seleccionar canal para pantalla ${i+1}">${options}</select></div><div class="mv-video-wrap"><video class="mv-video" data-mv-video="${i}" playsinline controls muted></video><div class="mv-placeholder" data-mv-placeholder="${i}"><span class="mv-play-icon">▶</span><strong>Selecciona un canal</strong><span>Esta pantalla reproducirá su señal de forma independiente.</span></div></div><div class="mv-foot"><span class="mv-title" data-mv-title="${i}">Sin canal</span><span class="mv-state" data-mv-state="${i}">EN ESPERA</span><button class="mv-audio" data-mv-audio="${i}" title="Activar audio">🔇 Audio</button><button class="mv-stop" data-mv-stop="${i}" title="Detener esta pantalla">■</button></div></article>`).join('');wireMvDrag();mvPlayers=Array.from({length:4},()=>({hls:null,channelId:'',state:'EN ESPERA'}));if(!channels.length)$('#mvStatus').textContent='Primero importa una lista M3U o añade canales en el editor.';else $('#mvStatus').textContent=`${channels.length} canales disponibles. Elige hasta ${mvCount} para verlos juntos.`;refreshMvProfiles($('#mvProfileSelect')?.value||'')}
function playMvSlot(i,cid){stopMvSlot(i);const c=findChannel(cid);if(!c){$('#mvStatus').textContent='Elige un canal válido.';return}const url=c.url||c.signals?.find(s=>s.url)?.url;if(!url){toast('Este canal no tiene una señal válida.','error');return}const v=document.querySelector(`[data-mv-video="${i}"]`),ph=document.querySelector(`[data-mv-placeholder="${i}"]`),title=document.querySelector(`[data-mv-title="${i}"]`),state=document.querySelector(`[data-mv-state="${i}"]`),audio=document.querySelector(`[data-mv-audio="${i}"]`);if(!v)return;mvPlayers[i]={hls:null,channelId:cid,state:'CONECTANDO'};title.textContent=c.name;state.textContent='CONECTANDO';state.classList.remove('error');ph.classList.add('hidden');v.muted=true;audio.textContent='🔇 Audio';audio.classList.remove('active');const done=()=>{state.textContent='EN DIRECTO';state.classList.remove('error');$('#mvStatus').textContent=`Pantalla ${i+1}: ${c.name}`};const fail=()=>{state.textContent='ERROR';state.classList.add('error');ph.classList.remove('hidden');ph.querySelector('strong').textContent='No se pudo reproducir';ph.querySelector('span:last-child').textContent='Prueba otra señal o revisa si el servidor permite la reproducción desde esta página.'};v.addEventListener('playing',done,{once:true});v.addEventListener('error',fail,{once:true});const isHls=/\.m3u8(?:$|[?#])/i.test(url)||/m3u8/i.test(c.type||'');if(isHls&&window.Hls&&Hls.isSupported()){const h=new Hls({enableWorker:true,lowLatencyMode:false,backBufferLength:15,maxBufferLength:20});mvPlayers[i].hls=h;h.on(Hls.Events.ERROR,(_,d)=>{if(d.fatal)fail()});h.on(Hls.Events.MANIFEST_PARSED,()=>v.play().catch(()=>{state.textContent='LISTO PARA REPRODUCIR';ph.classList.remove('hidden');ph.querySelector('strong').textContent='Pulsa reproducir';ph.querySelector('span:last-child').textContent='El navegador requiere iniciar esta señal manualmente.'}));h.loadSource(url);h.attachMedia(v)}else{v.src=url;v.load();v.play().catch(()=>{state.textContent='LISTO PARA REPRODUCIR';ph.classList.remove('hidden');ph.querySelector('strong').textContent='Pulsa reproducir';ph.querySelector('span:last-child').textContent='El navegador requiere iniciar esta señal manualmente.'})}}
function mvSwapSlots(a,b){if(a===b||a<0||b<0||a>=mvCount||b>=mvCount)return;const sa=document.querySelector(`[data-mv-select="${a}"]`),sb=document.querySelector(`[data-mv-select="${b}"]`);if(!sa||!sb)return;const ca=sa.value,cb=sb.value;const resume=(i,cid)=>{if(cid){const sel=document.querySelector(`[data-mv-select="${i}"]`);if(sel)sel.value=cid;playMvSlot(i,cid)}else{stopMvSlot(i);const sel=document.querySelector(`[data-mv-select="${i}"]`);if(sel)sel.value='';const title=document.querySelector(`[data-mv-title="${i}"]`);if(title)title.textContent='Sin canal'}};resume(a,cb);resume(b,ca);toast(`Pantallas ${a+1} y ${b+1} intercambiadas.`,'success')}
function setMvExpanded(on){const page=$('#pageMultiview');if(!page)return;document.body.classList.toggle('mv-expanded',on);$('#mvExitExpand')?.classList.toggle('hidden',!on);const b=$('#mvExpandBtn');if(b){b.textContent=on?'↙ Restaurar':'⛶ Expandir';b.title=on?'Salir de la vista expandida':'Expandir Multiview a pantalla completa'}if(on&&page.requestFullscreen&&!document.fullscreenElement)page.requestFullscreen().catch(()=>{});else if(!on&&document.fullscreenElement)document.exitFullscreen?.().catch(()=>{})}
function wireMvDrag(){const root=$('#multiviewGrid');if(!root||root.dataset.dragReady)return;root.dataset.dragReady='1';let from=null;root.addEventListener('dragstart',e=>{const card=e.target.closest('[data-mv-slot]');if(!card)return;from=Number(card.dataset.mvSlot);card.classList.add('mv-dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(from))});root.addEventListener('dragend',e=>{e.target.closest('[data-mv-slot]')?.classList.remove('mv-dragging');root.querySelectorAll('.mv-drop-target').forEach(x=>x.classList.remove('mv-drop-target'));from=null});root.addEventListener('dragover',e=>{const card=e.target.closest('[data-mv-slot]');if(!card)return;e.preventDefault();e.dataTransfer.dropEffect='move';root.querySelectorAll('.mv-drop-target').forEach(x=>x.classList.remove('mv-drop-target'));card.classList.add('mv-drop-target')});root.addEventListener('dragleave',e=>{if(!root.contains(e.relatedTarget))root.querySelectorAll('.mv-drop-target').forEach(x=>x.classList.remove('mv-drop-target'))});root.addEventListener('drop',e=>{const card=e.target.closest('[data-mv-slot]');if(!card)return;e.preventDefault();const a=from,b=Number(card.dataset.mvSlot);root.querySelectorAll('.mv-drop-target').forEach(x=>x.classList.remove('mv-drop-target'));if(a!==null&&Number.isFinite(b))mvSwapSlots(a,b)})}
